Run the same check on the release candidate:

```javascript
async function verifyRoundTrip(rows) {
  const source = JSON.stringify(rows);
  const imported = await importRows(source);
  const exported = await exportRows(imported);
  const restored = JSON.parse(exported);

  if (restored.length !== rows.length) {
    throw new Error("The importer changed the row count");
  }

  for (const [index, row] of rows.entries()) {
    const expected = Object.keys(row).sort();
    const actual = Object.keys(restored[index]).sort();
    if (JSON.stringify(actual) !== JSON.stringify(expected)) {
      throw new Error(`Field names changed in row ${index}`);
    }
  }

  return { rows: restored.length, status: "passed" };
}
```

